}
.py-3 {
  padding-top: var(--space-3);
  padding-bottom: var(--space-3);
}

/* Margin */
.m-0 {
  margin: 0;
}
.mt-2 {
  margin-top: var(--space-2);
}
.mt-3 {
  margin-top: var(--space-3);
}
.mt-4 {
  margin-top: var(--space-4);
}
.mb-2 {
  margin-bottom: var(--space-2);
}
.mb-3 {
  margin-bottom: var(--space-3);
}
.mb-4 {
  margin-bottom: var(--space-4);
}
.ml-auto {
  margin-left: auto;
}
.mr-auto {
  margin-right: auto;
}

/* Width/Height */
.w-full {
  width: 100%;
}
.h-full {
  height: 100%;
}
.min-h-screen {
  min-height: 100vh;
}

/* Position */
.relative {
  position: relative;
}
.absolute {
  position: absolute;
}
.fixed {
  position: fixed;
}
.inset-0 {
  inset: 0;
}

/* Text */
.text-xs {
  font-size: var(--text-xs);
}
.text-sm {
  font-size: var(--text-sm);
}
.text-base {
  font-size: var(--text-base);
}
.text-lg {
  font-size: var(--text-lg);
}
.text-xl {
  font-size: var(--text-xl);
}
.text-2xl {
  font-size: var(--text-2xl);
}
.text-3xl {
  font-size: var(--text-3xl);
}
.font-normal {
  font-weight: var(--font-normal);
}
.font-medium {
  font-weight: var(--font-medium);
}
.font-semibold {
  font-weight: var(--font-semibold);
}
.font-bold {
  font-weight: var(--font-bold);
}
.text-center {
  text-align: center;
}
.text-right {
  text-align: right;
}
.leading-tight {
  line-height: var(--leading-tight);
}
.leading-normal {
  line-height: var(--leading-normal);
}
.truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Colors */
.text-primary {
  color: var(--color-text-primary);
}
.text-secondary {
  color: var(--color-text-secondary);
}
.text-disabled {
  color: var(--color-text-disabled);
}
.text-success {
  color: var(--color-success);
}
.text-error {
  color: var(--color-error);
}
.text-lilac {
  color: var(--color-lilac-dark);
}
.text-mint {
  color: var(--color-mint-dark);
}

/* Background */
.bg-surface {
  background: var(--color-surface);
}
.bg-container {
  background: var(--color-container);
}
.bg-glass {
  background: var(--color-container-glass);
}
.bg-lilac {
  background: var(--color-lilac);
}
.bg-mint {
  background: var(--color-mint);
}
.bg-success-light {
  background: var(--color-success-light);
}
.bg-error-light {
  background: var(--color-error-light);
}

/* Border */
.border {
  border: 1px solid var(--color-border);
}
.border-glass {
  border: 1px solid var(--color-border-glass);
}
.border-lilac {
  border-color: var(--color-lilac);
}
.rounded-md {
  border-radius: var(--radius-md);
}
.rounded-lg {
  border-radius: var(--radius-lg);
}
.rounded-xl {
  border-radius: var(--radius-xl);
}
.rounded-full {
  border-radius: var(--radius-full);
}

/* Shadow */
.shadow-sm {
  box-shadow: var(--shadow-sm);
}
.shadow-md {
  box-shadow: var(--shadow-md);
}
.shadow-lg {
  box-shadow: var(--shadow-lg);
}
.shadow-glass {
  box-shadow: var(--shadow-glass);
}

/* Overflow */
.overflow-hidden {
  overflow: hidden;
}
.overflow-auto {
  overflow: auto;
}
.overflow-x-auto {
  overflow-x: auto;
}

/* Cursor */
.cursor-pointer {
  cursor: pointer;
}
.cursor-grab {
  cursor: grab;
}
.cursor-grabbing {
  cursor: grabbing;
}

/* Transitions */
.transition {
  transition: all var(--transition-base);
}
.transition-fast {
  transition: all var(--transition-fast);
}

/* Animation */
.animate-fadeIn {
  animation: fadeIn var(--transition-base) ease;
}
.animate-slideUp {
  animation: slideUp var(--transition-base) ease;
}
.animate-spin {
  animation: spin 1s linear infinite;
}
.animate-pulse {
  animation: pulse 2s ease-in-out infinite;
}

/* Opacity */
.opacity-0 {
  opacity: 0;
}
.opacity-50 {
  opacity: 0.5;
}
.opacity-75 {
  opacity: 0.75;
}
.opacity-100 {
  opacity: 1;
}

/* Z-index */
.z-0 {
  z-index: 0;
}
.z-10 {
  z-index: 10;
}
.z-20 {
  z-index: 20;
}
.z-50 {
  z-index: 50;
}

import { defineConfig } from "vite";
import { viteSingleFile } from "vite-plugin-singlefile";

// Get the app to build from environment variable or default to fitness-app
const app = process.env.BUILD_APP || "fitness-app";

export default defineConfig({
  plugins: [viteSingleFile()],
  build: {
    outDir: "dist",
    emptyOutDir: false, // Don't clear dist so we can build multiple apps
    rollupOptions: {
      input: `${app}.html`,
      output: {
        entryFileNames: `${app}.js`,
        assetFileNames: `${app}.[ext]`,
      },
    },
  },
});

