// Express server setup
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3001;

const app = express();
app.use(express.json());
app.use(
  cors({
    origin: "*",
    exposedHeaders: ["Mcp-Session-Id"],
  }),
);

// Session management for MCP connections
const transports: { [sessionId: string]: StreamableHTTPServerTransport } = {};

// MCP POST handler - main entry point for MCP requests
const mcpPostHandler = async (req: Request, res: Response) => {
  const sessionId = req.headers["mcp-session-id"] as string | undefined;

  try {
    let transport: StreamableHTTPServerTransport;

    if (sessionId && transports[sessionId]) {
      // Existing session
      transport = transports[sessionId];
    } else if (!sessionId && isInitializeRequest(req.body)) {
      // New session initialization - eventStore enables resumability for MCP Apps
      const eventStore = new InMemoryEventStore();
      transport = new StreamableHTTPServerTransport({
        sessionIdGenerator: () => randomUUID(),
        eventStore,
        onsessioninitialized: (sid) => {
          console.log(`[MCP] Session initialized: ${sid}`);
          transports[sid] = transport;
        },
      });

      transport.onclose = () => {
        const sid = transport.sessionId;
        if (sid && transports[sid]) {
          console.log(`[MCP] Session closed: ${sid}`);
          delete transports[sid];
        }
      };

      const server = await getServer();
      await server.connect(transport);
      await transport.handleRequest(req, res, req.body);
      return;
    } else {
      // Invalid request
      res.status(400).json({
        jsonrpc: "2.0",
        error: { code: -32000, message: "Bad Request: No valid session ID" },
        id: null,
      });
      return;
    }

    await transport.handleRequest(req, res, req.body);
  } catch (error) {
    console.error("[MCP] Error handling request:", error);
    if (!res.headersSent) {
      res.status(500).json({
        jsonrpc: "2.0",
        error: { code: -32603, message: "Internal server error" },
        id: null,
      });
    }
  }
};

// Routes
app.post("/mcp", mcpPostHandler);

app.get("/mcp", async (req: Request, res: Response) => {
  const sessionId = req.headers["mcp-session-id"] as string | undefined;
  if (!sessionId || !transports[sessionId]) {
    res.status(400).send("Invalid or missing session ID");
    return;
  }
  const transport = transports[sessionId];
  await transport.handleRequest(req, res);
});

app.delete("/mcp", async (req: Request, res: Response) => {
  const sessionId = req.headers["mcp-session-id"] as string | undefined;
  if (!sessionId || !transports[sessionId]) {
    res.status(400).send("Invalid or missing session ID");
    return;
  }
  try {
    const transport = transports[sessionId];
    await transport.handleRequest(req, res);
  } catch (error) {
    console.error("[MCP] Error handling session termination:", error);
    if (!res.headersSent) {
      res.status(500).send("Error processing session termination");
    }
  }
});

// Health check endpoint
app.get("/health", (_req: Request, res: Response) => {
  res.json({
    status: "ok",
    server: "travel-booking-mcp",
    sessions: Object.keys(transports).length,
  });
});

// Start server
app.listen(PORT, () => {
  console.log(
    `[Travel Booking MCP Server] Running at http://localhost:${PORT}/mcp`,
  );
  console.log(`[Health Check] http://localhost:${PORT}/health`);
});

// Graceful shutdown
process.on("SIGINT", async () => {
  console.log("\n[MCP] Shutting down...");
  for (const sessionId in transports) {
    try {
      await transports[sessionId].close();
      delete transports[sessionId];
    } catch (error) {
      console.error(`[MCP] Error closing session ${sessionId}:`, error);
    }
  }
  process.exit(0);
});

/**
 * Flight booking data layer for the Airline Booking demo.
 * Contains mock airport/airline data, flight search, seat selection, and booking logic.
 */

// Type definitions
export type CabinClass = "economy" | "business" | "first";
export type SeatStatus = "available" | "occupied" | "selected" | "exit";

/**
 * Represents an airport.
 */
export interface Airport {
  code: string;
  city: string;
  name: string;
  country: string;
}

/**
 * Represents an airline.
 */
export interface Airline {
  code: string;
  name: string;
  color: string; // Brand color for UI
}

/**
 * Represents a single seat on a flight.
 */
export interface Seat {
  id: string; // e.g., "12A"
  row: number;
  position: string; // A-F
  status: SeatStatus;
  isWindow: boolean;
  isAisle: boolean;
  isExitRow: boolean;
  price: number; // Extra charge for premium seats
}

/**
 * Represents a flight option.
 */
export interface Flight {
  id: string;
  airline: Airline;
  flightNumber: string;
  origin: Airport;
  destination: Airport;
  departureTime: string; // HH:MM
  arrivalTime: string;
  duration: string; // e.g., "5h 30m"
  stops: number;
  aircraft: string;
  price: number; // Per passenger
  cabinClass: CabinClass;
  seatsAvailable: number;
}

/**
 * Represents a flight search result with multiple flights.
 */
export interface FlightSearch {
  id: string;
  flights: Flight[];
  searchParams: {
    origin: string;
    destination: string;
    date: string;
    passengers: number;
    cabinClass: CabinClass;
  };
  selectedFlightId?: string;
  selectedSeats?: string[];
}

/**
 * Passenger information for booking.
 */
export interface Passenger {
  name: string;
  email: string;
  phone: string;
}

/**
 * Represents a completed booking.
 */
export interface Booking {
  confirmationNumber: string;
  flight: Flight;
  passengers: Passenger[];
  seats: string[];
  totalPrice: number;
  bookedAt: string;
}

